package com.pastestack.assetgraph

import spray.json._
import java.nio.file.{Files, Path}
import java.security.MessageDigest

/**
 * Asset manifest runtime library for Scala.
 * 
 * Reads manifests generated by paste-assetgraph (Rust).
 * Use with Akka HTTP, Pekko HTTP, or any Scala HTTP server.
 */
case class AssetVersion(
  hash: String,
  version: Int,
  output: String,
  timestamp: String
)

case class AssetEntry(
  source: String,
  output: String,
  hash: String,
  version: Int,
  dependencies: Seq[String] = Seq.empty,
  history: Seq[AssetVersion] = Seq.empty
)

case class Manifest(
  version: String,
  generated: String,
  assets: Map[String, AssetEntry]
) {
  
  /**
   * Resolve source path to versioned output path.
   */
  def resolve(sourcePath: String, debug: Boolean = false): Option[String] = {
    assets.get(sourcePath).map { entry =>
      if (debug) entry.source else entry.output
    }
  }
  
  /**
   * Get output path for specific version (for rollback).
   */
  def getVersion(key: String, version: Option[Int] = Option.empty): Option[String] = {
    assets.get(key).flatMap { entry =>
      version match {
        case None | Some(v) if v == entry.version => Some(entry.output)
        case Some(v) => entry.history.find(_.version == v).map(_.output)
      }
    }
  }
  
  /**
   * Generate JAM URL for bundled JS modules.
   * Format: /paste/{timestamp}/{module+version,module+version,...}.min.js
   */
  def jamUrl(modules: Seq[String], debug: Boolean = false): String = {
    jamJsUrl(modules, debug)
  }
  
  /**
   * Generate JAM URL for JS modules.
   */
  def jamJsUrl(modules: Seq[String], debug: Boolean = false): String = {
    jamUrlForType(modules, "js", debug)
  }
  
  /**
   * Generate JAM URL for CSS modules.
   */
  def jamCssUrl(modules: Seq[String], debug: Boolean = false): String = {
    jamUrlForType(modules, "css", debug)
  }
  
  /**
   * Generate JAM URL with per-group timestamp.
   * Timestamp is based on when THIS GROUP of modules last changed,
   * enabling cache reuse across deploys when modules haven't changed.
   */
  private def jamUrlForType(modules: Seq[String], assetType: String, debug: Boolean): String = {
    var latestTimestamp: Long = 0L
    val moduleVersions = modules.flatMap { m =>
      val key = s"$assetType/${m.replace('.', '/')}.$assetType"
      assets.get(key).map { e =>
        // Track latest timestamp for this group
        scala.util.Try(e.timestamp.toLong).foreach { ts =>
          if (ts > latestTimestamp) latestTimestamp = ts
        }
        s"$m+v${e.version}.0"
      }
    }
    
    // Use group timestamp if available, otherwise fall back to manifest version
    val groupTimestamp = if (latestTimestamp > 0) latestTimestamp.toString else version
    val suffix = if (debug) s".$assetType" else s".min.$assetType"
    
    s"/paste/$groupTimestamp/${moduleVersions.mkString(",")}$suffix"
  }
  
  /**
   * Generate bootstrap script tag for JAM modules.
   * 
   * This pre-marks modules as isLoading before the script loads,
   * allowing deferred loading until paste.js is ready.
   * 
   * If bundle size is under inlineThreshold bytes, inlines the entire bundle.
   * 
   * @param modules Module names to load
   * @param cdnBase CDN base URL (e.g., "//cdn.example.com")
   * @param inlineThreshold If bundle size < this, inline it (0 = never inline)
   * @return HTML script tag(s)
   */
  def jamBootstrap(
    modules: Seq[String],
    cdnBase: String = "",
    inlineThreshold: Int = 0
  ): String = {
    val url = cdnBase + jamJsUrl(modules, debug = false)
    
    // Build isLoading assignments: d('paste.dom').isLoading=d('paste.event').isLoading=!0
    val loadingAssignments = modules.map(m => s"d('$m').isLoading").mkString("=") + "=!0"
    
    // Check if we should inline
    if (inlineThreshold > 0) {
      val totalSize = modules.flatMap { m =>
        val key = s"js/${m.replace('.', '/')}.js"
        assets.get(key).map(_.source)
      }.map { path =>
        scala.util.Try(new java.io.File(path).length()).getOrElse(0L)
      }.sum
      
      if (totalSize < inlineThreshold) {
        // Inline the entire bundle
        val content = modules.flatMap { m =>
          val key = s"js/${m.replace('.', '/')}.js"
          assets.get(key).map(_.source)
        }.flatMap { path =>
          scala.util.Try(scala.io.Source.fromFile(path).mkString).toOption
        }.mkString("\n")
        
        return s"""<script type="text/javascript">(function(d){$loadingAssignments;})(paste.define);$content</script>"""
      }
    }
    
    // External script with bootstrap
    s"""<script type="text/javascript">(function(d,r){$loadingAssignments;r('$url');})(paste.define,paste.require);</script>"""
  }
  
  /**
   * Generate bootstrap for CSS modules.
   */
  def jamCssBootstrap(modules: Seq[String], cdnBase: String = ""): String = {
    val url = cdnBase + jamCssUrl(modules, debug = false)
    s"""<link rel="stylesheet" href="$url"/>"""
  }
  
  /**
   * Get all dependencies for a module (recursive, topologically sorted).
   */
  def getDependencies(module: String): Seq[String] = {
    var visited = Set.empty[String]
    var result = Seq.empty[String]
    
    def visit(m: String): Unit = {
      if (visited.contains(m)) return
      visited += m
      
      val key = s"js/${m.replace(".", "/")}.js"
      assets.get(key).foreach { entry =>
        entry.dependencies.foreach(visit)
        result :+= m
      }
    }
    
    visit(module)
    result
  }
}

object Manifest extends DefaultJsonProtocol {
  
  implicit val assetVersionFormat: RootJsonFormat[AssetVersion] = jsonFormat4(AssetVersion)
  
  implicit val assetEntryFormat: RootJsonFormat[AssetEntry] = jsonFormat(
    AssetEntry, "source", "output", "hash", "version", "dependencies", "history"
  )
  
  implicit val manifestFormat: RootJsonFormat[Manifest] = jsonFormat3(Manifest.apply)
  
  /**
   * Load manifest from file path.
   */
  def load(path: Path): Manifest = {
    val content = new String(Files.readAllBytes(path))
    content.parseJson.convertTo[Manifest]
  }
  
  /**
   * Load manifest from file path string.
   */
  def load(path: String): Manifest = load(Path.of(path))
  
  /**
   * Load manifest from classpath resource.
   */
  def loadFromResource(resourcePath: String): Manifest = {
    val stream = getClass.getResourceAsStream(resourcePath)
    if (stream == null) {
      throw new IllegalArgumentException(s"Resource not found: $resourcePath")
    }
    try {
      val content = scala.io.Source.fromInputStream(stream).mkString
      content.parseJson.convertTo[Manifest]
    } finally {
      stream.close()
    }
  }
}
